BEGIN;

CREATE SCHEMA retail;
SET search_path TO retail, public;

CREATE TABLE stores (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL UNIQUE,
  city text,
  region text NOT NULL CHECK (region IN ('Northeast', 'Midwest', 'South', 'West', 'Online')),
  opened_on date NOT NULL
);

CREATE TABLE products (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  sku text NOT NULL UNIQUE,
  name text NOT NULL UNIQUE,
  category text NOT NULL CHECK (category IN ('Apparel', 'Footwear', 'Accessories', 'Home', 'Beauty', 'Outdoor', 'Electronics', 'Toys')),
  unit_cost numeric(10,2) NOT NULL CHECK (unit_cost > 0),
  list_price numeric(10,2) NOT NULL CHECK (list_price > 0),
  CHECK (unit_cost < list_price)
);

CREATE TABLE customers (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_number text NOT NULL UNIQUE,
  full_name text NOT NULL UNIQUE,
  region text NOT NULL CHECK (region IN ('Northeast', 'Midwest', 'South', 'West')),
  signed_up_on date NOT NULL CHECK (signed_up_on BETWEEN DATE '2023-06-01' AND DATE '2026-03-31'),
  loyalty_tier text NOT NULL CHECK (loyalty_tier IN ('bronze', 'silver', 'gold'))
);

CREATE TABLE orders (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  order_number text NOT NULL UNIQUE,
  customer_id bigint NOT NULL REFERENCES customers(id),
  store_id bigint NOT NULL REFERENCES stores(id),
  ordered_at date NOT NULL CHECK (ordered_at BETWEEN DATE '2024-01-01' AND DATE '2026-03-31'),
  status text NOT NULL CHECK (status IN ('completed', 'cancelled')),
  amount_charged numeric(12,2) NOT NULL CHECK (amount_charged > 0)
);

CREATE TABLE order_lines (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  order_id bigint NOT NULL REFERENCES orders(id),
  product_id bigint NOT NULL REFERENCES products(id),
  quantity integer NOT NULL CHECK (quantity BETWEEN 1 AND 10),
  unit_price numeric(10,2) NOT NULL CHECK (unit_price > 0),
  discount_amount numeric(10,2) NOT NULL CHECK (discount_amount >= 0),
  UNIQUE (order_id, product_id),
  CHECK (discount_amount <= quantity * unit_price)
);

CREATE INDEX orders_customer_idx ON orders (customer_id);
CREATE INDEX orders_store_idx ON orders (store_id);
CREATE INDEX orders_ordered_at_idx ON orders (ordered_at);
CREATE INDEX order_lines_order_idx ON order_lines (order_id);
CREATE INDEX order_lines_product_idx ON order_lines (product_id);


